{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C39"],
      "claim": "In patients with myasthenia gravis, pyridostigmine—the query molecule—had an oral bioavailability of 7.6%, below the 20% threshold; this is direct human evidence for low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Neostigmine, a close quaternary ammonium dimethylcarbamate analogue, had absolute oral bioavailability of 2.0 ± 0.33% after oral dosing vs i.v. in fasted patients, demonstrating very poor absorption for this charged carbamate class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "A second neostigmine study estimated oral bioavailability at 1–2%, confirming that the quaternary carbamate scaffold consistently yields F far below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Bambuterol, a dimethylcarbamate-containing drug, has ~10% oral bioavailability in healthy adults, indicating carbamate-containing structures can be limited by absorption/first-pass even without a permanent charge.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Acamprosate, a small polar molecule with poor permeability, has ~11% fasting oral bioavailability, supporting that polar/charged small molecules often fail the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Direct human evidence identifies the query as pyridostigmine with oral bioavailability ~7.6%, below the 20% cutoff. Closely related quaternary ammonium carbamates (neostigmine) show 1–2% F, and other carbamate/polar small molecules are also low. High-F comparators (aspirin, methadone) have negligible transfer scores and are structurally unrelated, so they do not outweigh the direct evidence. Prediction: low.",
  "evidence_gaps": [
    "The 7.6% pyridostigmine value is from a comparative statement rather than a dedicated absolute bioavailability study; formulation/salt effects are not specified.",
    "No data on whether fed state or modified-release formulation could raise pyridostigmine F above 20%."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

